212→// Tags used by oh-my-opencode and similar orchestration tools to inject
213→// context into the conversation with role "user" — not actual user prompts.
214→const (
215→	systemReminderOpen  = "<system-reminder>"
216→	systemReminderClose = "</system-reminder>"
217→)
218→
219→// isSystemReminderOnly reports whether content consists entirely of
220→// <system-reminder>...</system-reminder> blocks (after trimming whitespace).
221→// Delegates to stripSystemReminders to correctly handle multiple blocks
222→// (HasPrefix+HasSuffix would false-positive on "<sr>a</sr>real<sr>b</sr>").
223→func isSystemReminderOnly(content string) bool {
224→	if strings.TrimSpace(content) == "" {
225→		return false
226→	}
227→	return stripSystemReminders(content) == ""
228→}
229→
230→// stripSystemReminders removes all <system-reminder>...</system-reminder>
231→// sections from content and returns the remaining text. If nothing remains
232→// after stripping (or the content was system-reminder-only), it returns "".
233→func stripSystemReminders(content string) string {
234→	result := content
235→	for {
236→		start := strings.Index(result, systemReminderOpen)
237→		if start == -1 {
238→			break
239→		}
240→		end := strings.Index(result[start:], systemReminderClose)
241→		if end == -1 {
242→			break
243→		}
244→		end += start + len(systemReminderClose)
245→		result = result[:start] + result[end:]
246→	}
247→	return strings.TrimSpace(result)
248→}
249→
250→// ExtractAllUserPrompts extracts all user prompts from raw export JSON transcript bytes.
251→// This is a package-level function used by the condensation path.
252→// Messages that consist entirely of <system-reminder> tags (e.g. from oh-my-opencode)
253→// are excluded. Mixed messages have their system-reminder sections stripped.
254→func ExtractAllUserPrompts(data []byte) ([]string, error) {
255→	session, err := ParseExportSession(data)
256→	if err != nil {
257→		return nil, err
258→	}
259→	if session == nil {
260→		return nil, nil
261→	}
262→
263→	var prompts []string
264→	for _, msg := range session.Messages {
265→		if msg.Info.Role != roleUser {
266→			continue
267→		}
268→		content := ExtractTextFromParts(msg.Parts)
269→		if content == "" {
270→			continue
271→		}
272→		if isSystemReminderOnly(content) {
273→			continue
274→		}
275→		content = stripSystemReminders(content)
276→		if content != "" {
277→			prompts = append(prompts, content)
278→		}
279→	}
280→	return prompts, nil
281→}
282→
283→// CalculateTokenUsage computes token usage from assistant messages starting at the given offset.
284→func (a *OpenCodeAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
285→	session, err := ParseExportSession(transcriptData)
286→	if err != nil {
287→		return nil, fmt.Errorf("failed to parse transcript for token usage: %w", err)
288→	}
289→	if session == nil {
290→		return nil, nil //nolint:nilnil // nil usage for empty data is expected
291→	}
292→
293→	usage := &agent.TokenUsage{}
294→	for i := fromOffset; i < len(session.Messages); i++ {
295→		msg := session.Messages[i]
296→		if msg.Info.Role != roleAssistant || msg.Info.Tokens == nil {
297→			continue
298→		}
299→		usage.InputTokens += msg.Info.Tokens.Input
300→		usage.OutputTokens += msg.Info.Tokens.Output
301→		usage.CacheReadTokens += msg.Info.Tokens.Cache.Read
302→		usage.CacheCreationTokens += msg.Info.Tokens.Cache.Write
303→		usage.APICallCount++
304→	}
305→
306→	return usage, nil
307→}
