// tryAgentCommitFastPath skips content detection for commits during agent sessions.
// Returns true if the fast path was taken (trailer added or attempt made),
// false if the caller should continue with normal content detection.
//
// The fast path activates when either:
//   - No TTY is available (agent subprocess, CI) and an ACTIVE session exists, or
//   - commit_linking="always" and an ACTIVE or IDLE session exists. IDLE sessions
//     are included because the user explicitly opted into always-linking and commonly
//     commits after an agent turn finishes (session transitions ACTIVE→IDLE on TurnEnd).
//     Without this, broken transcript exports (e.g., invalid JSON from `opencode export`)
//     cause content detection to fail silently, leaving user commits unlinked.
func (s *ManualCommitStrategy) tryAgentCommitFastPath(ctx context.Context, commitMsgFile string, sessions []*SessionState, source string) bool {
	noTTY := !hasTTY()
	alwaysLink := false
	if !noTTY {
		if stngs, err := settings.Load(ctx); err == nil {
			alwaysLink = stngs.GetCommitLinking() == settings.CommitLinkingAlways
		}
	}
	if !noTTY && !alwaysLink {
		return false
	}
	logCtx := logging.WithComponent(ctx, "checkpoint")
	// First pass: ACTIVE sessions (agent mid-turn).
	for _, state := range sessions {
		if state.Phase.IsActive() {
			_ = s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source) //nolint:errcheck // always returns nil; kept for signature stability
			return true
		}
	}
	// Second pass: IDLE sessions (only when commit_linking="always").
	// This handles the common case where a user commits after an agent turn finishes.
	// Without a TTY (agent subprocess), IDLE sessions are not linked — the agent
	// should be ACTIVE when it commits.
	if alwaysLink {
		for _, state := range sessions {
			if state.Phase == session.PhaseIdle {
				_ = s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source) //nolint:errcheck // always returns nil; kept for signature stability
				return true
			}
		}
	}
	return false
}

