1653→// tryAgentCommitFastPath skips content detection for mid-turn agent commits.
1654→// Returns true if the fast path was taken (trailer added or attempt made),
1655→// false if the caller should continue with normal content detection.
1656→//
1657→// The fast path activates when an ACTIVE session exists and either:
1658→//   - No TTY is available (agent subprocess, CI), or
1659→//   - commit_linking="always" (user opted into auto-linking — needed because
1660→//     some agents like Gemini subagents commit mid-turn from processes that
1661→//     have /dev/tty but can't respond to prompts, and content detection fails
1662→//     since the shadow branch doesn't exist yet).
1663→func (s *ManualCommitStrategy) tryAgentCommitFastPath(ctx context.Context, commitMsgFile string, sessions []*SessionState, source string) bool {
1664→	skipContentDetection := !hasTTY()
1665→	if !skipContentDetection {
1666→		if stngs, err := settings.Load(ctx); err == nil {
1667→			skipContentDetection = stngs.GetCommitLinking() == settings.CommitLinkingAlways
1668→		}
1669→	}
1670→	if !skipContentDetection {
1671→		return false
1672→	}
1673→	logCtx := logging.WithComponent(ctx, "checkpoint")
1674→	for _, state := range sessions {
1675→		if state.Phase.IsActive() {
1676→			_ = s.addTrailerForAgentCommit(logCtx, commitMsgFile, state, source) //nolint:errcheck // always returns nil; kept for signature stability
1677→			return true
1678→		}
1679→	}
1680→	return false
1681→}
